#!/usr/bin/env pwsh
# Generated by fmverify. Fetches the z3 CLI used to run fmtranslator's bounded SMT-LIB claims.
#
# This is the CLI, not the Microsoft.Z3 package the model uses. It is a pinned GitHub release
# asset, hash-verified before use, and it lands in .tools/ so nothing is installed globally or
# looked up on PATH. The script is only run by verify.ps1 when a translation/ directory exists.
$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"

# Deliberately not Get-FileHash, for the reason fetch-solver.ps1 gives.
function Get-Sha256Hex([string] $path) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $stream = [System.IO.File]::OpenRead($path)
    try { $bytes = $sha.ComputeHash($stream) }
    finally { $stream.Dispose(); $sha.Dispose() }
    return (($bytes | ForEach-Object { $_.ToString("x2") }) -join "")
}

Push-Location $PSScriptRoot
try {
    $version = "5.3.3"
    $arch = [System.Runtime.InteropServices.RuntimeInformation]::OSArchitecture

    if ($IsWindows -or $env:OS -eq "Windows_NT") {
        if ($arch -eq "Arm64") { $asset = "z3-5.3.3-arm64-win.zip"; $sha256 = "af442c9a8ac995ae0be789e33e60a5670d5e3895fd4f19d333b242b1b8afff24" }
        else                   { $asset = "z3-5.3.3-x64-win.zip";   $sha256 = "4e48624a6895b49606b3cf91ca4fbcc069fb2973b9706532170a144baa3fd798" }
    } elseif ($IsMacOS) {
        if ($arch -eq "Arm64") { $asset = "z3-5.3.3-arm64-osx-13.3.zip"; $sha256 = "6957e6c75266d7ca8fa77030e86e83d78624567dcdf34cc11f4192fdc6f93c6b" }
        else                   { $asset = "z3-5.3.3-x64-osx-13.3.zip";   $sha256 = "ace69787d5a21762154b103abe68178188f38e02362fb0f82d346621af90f8e7" }
    } elseif ($IsLinux) {
        if ($arch -eq "Arm64") { $asset = "z3-5.3.3-arm64-glibc-2.38.zip"; $sha256 = "d4586e12af2609499e07d615ac578256125b19f396f0d6ca358fe7b22988bcec" }
        else                   { $asset = "z3-5.3.3-x64-glibc-2.39.zip";   $sha256 = "d56f60b06f432f33de5810f7f1a384a339131f361e2d54d08ea83eea14326880" }
    } else {
        Write-Error "z3 $version has no CLI release for this platform ($arch)."
    }

    $url     = "https://github.com/Z3Prover/z3/releases/download/z3-$version/$asset"
    $tools   = Join-Path $PSScriptRoot ".tools"
    $zip     = Join-Path $tools $asset
    $install = Join-Path $tools "z3-$version"
    New-Item -ItemType Directory -Force $tools | Out-Null

    if (-not ((Test-Path $zip) -and ((Get-Sha256Hex $zip) -eq $sha256))) {
        Write-Host "Fetching z3 $version from $url"
        Invoke-WebRequest -Uri $url -OutFile $zip

        $actual = Get-Sha256Hex $zip
        if ($actual -ne $sha256) {
            Remove-Item $zip -Force
            Write-Error "z3 package hash mismatch. Refusing to use it.`n  expected $sha256`n  actual   $actual"
        }

        if (Test-Path $install) { Remove-Item $install -Recurse -Force }
    }

    $binary = if ($IsWindows -or $env:OS -eq "Windows_NT") { "z3.exe" } else { "z3" }
    if (-not (Test-Path (Join-Path $install "bin/$binary"))) {
        if (Test-Path $install) { Remove-Item $install -Recurse -Force }
        $partial = "$install.partial"
        if (Test-Path $partial) { Remove-Item $partial -Recurse -Force }
        Add-Type -AssemblyName System.IO.Compression.FileSystem
        [System.IO.Compression.ZipFile]::ExtractToDirectory($zip, $partial)

        $root = Get-ChildItem $partial -Directory | Select-Object -First 1
        if (-not $root -or -not (Test-Path (Join-Path $root.FullName "bin/$binary"))) {
            Remove-Item $partial -Recurse -Force
            Write-Error "z3 archive did not contain bin/$binary."
        }

        Move-Item $root.FullName $install
        Remove-Item $partial -Recurse -Force -ErrorAction SilentlyContinue
    }

    if (-not ($IsWindows -or $env:OS -eq "Windows_NT")) {
        & chmod +x (Join-Path $install "bin/$binary")
    }

    Write-Host "z3 $version present and verified."
} finally { Pop-Location }
